#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

struct Matrix {
    long long mat[2][2];
    Matrix() {
        memset(mat, 0, sizeof(mat));
    }
    Matrix(long long a[2][2]) {
        for (int i=0; i<2; i++) {
            for (int j=0; j<2; j++) {
                mat[i][j] = a[i][j];
            }
        }
    }
    Matrix pow(long long power) const {
        Matrix result({{1,0},{0,1}});
        Matrix base(*this);
        while (power > 0) {
            if (power & 1) {
                result = result.multiply(base);
            }
            base = base.multiply(base);
            power >>= 1;
        }
        return result;
    }
    Matrix multiply(const Matrix& m) const {
        Matrix res;
        for (int i=0; i<2; i++) {
            for (int j=0; j<2; j++) {
                res.mat[i][j] = 0;
                for (int k=0; k<2; k++) {
                    res.mat[i][j] += mat[i][k] * m.mat[k][j];
                }
                res.mat[i][j] %= MOD;
            }
        }
        return res;
    }
};

long long powMod(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modExp(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

